void mainImage(out vec4 fragColor, in vec2 fragCoord) {
    // Normalize coordinates
    vec2 uv = fragCoord / iResolution.xy;

    // Correct for aspect ratio
    float aspectRatio = iResolution.x / iResolution.y;
    uv.x *= aspectRatio;

    // Logo properties
    float logoRadius = 0.05;           // Radius of the circular logo
    float borderThickness = 0.01;     // Thickness of the circle border
    vec2 velocity = vec2(0.5, 0.3);    // Velocity in screen space (units per second)

    // Calculate the effective bouncing area (account for edges)
    vec2 effectiveResolution = vec2(1.0) - logoRadius * 2.0;

    // Compute the current position of the circle
    vec2 pos = mod(iTime * velocity, effectiveResolution * 2.0); // Bouncing in [0, 2*area]
    if (pos.x > effectiveResolution.x) pos.x = 2.0 * effectiveResolution.x - pos.x; // Reflect X
    if (pos.y > effectiveResolution.y) pos.y = 2.0 * effectiveResolution.y - pos.y; // Reflect Y

    // Offset to ensure the circle stays fully within the bounds
    pos += logoRadius;

    // Distance from the current pixel to the circle's center
    float dist = length(uv - pos);

    // Render the inner circle
    float inside = step(dist, logoRadius);

    // Render the border (outer ring)
    float outer = step(dist, logoRadius + borderThickness);
    float circleBorder = outer - inside;

    // Render the screen border
    float screenBorderThickness = 0.02;  // Thickness of the screen border
    float screenBorder = step(uv.x, screenBorderThickness) +          // Left edge
                         step(uv.y, screenBorderThickness) +          // Bottom edge
                         step(1.0 - uv.x, screenBorderThickness) +    // Right edge
                         step(1.0 - uv.y, screenBorderThickness);     // Top edge
    screenBorder = min(screenBorder, 1.0); // Clamp value to prevent overlap

    // Colors
    vec4 backgroundColor = vec4(0.0, 0.0, 0.0, 1.0); // Black background
    vec4 screenBorderColor = vec4(0.0, 1.0, 0.0, 1.0); // Green screen border
    vec4 circleBorderColor = vec4(1.0, 1.0, 1.0, 1.0); // White circle border
    vec4 logoColor = vec4(1.0, 0.0, 0.0, 1.0);         // Red circle

    // Combine layers
    fragColor = mix(backgroundColor, screenBorderColor, screenBorder);  // Draw screen border
    fragColor = mix(fragColor, circleBorderColor, circleBorder);        // Draw circle border
    fragColor = mix(fragColor, logoColor, inside);                      // Draw inner circle
}
